import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Excel Template","description":"","frontmatter":{"prev":{"text":"Site","link":"/documentation/site/site"},"next":{"text":"Scraper Data","link":"/documentation/site/site-scraper-data"}},"headers":[],"relativePath":"documentation/site/site-excel-template.md","filePath":"documentation/site/site-excel-template.md","lastUpdated":1788551488000}`),a={name:`documentation/site/site-excel-template.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="excel-template" tabindex="-1">Excel Template <a class="header-anchor" href="#excel-template" aria-label="Permalink to “Excel Template”">​</a></h1><p>Manage your spreadsheet data source for automated form filling with native support for local Excel (<code>.xlsx</code>) files and Google Sheets integration.</p><img src="/image/upload-excel-template.png" alt="Upload Excel Template Interface" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Excel templates serve as the primary data source for your automated workflows. Excellent Data Filler reads row records sequentially or randomly and fills target web form inputs accordingly.</p><p>The extension supports two Excel data source types:</p><ul><li><strong>Upload Excel File</strong>: Upload local Excel (<code>.xlsx</code>) files directly into extension storage for fast, offline execution.</li><li><strong>Google Sheet (Beta)</strong>: Connect to Google Sheets for real-time cloud collaboration, automatic syncing, and multi-browser automation.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Strict <code>.xlsx</code> Format Requirement</strong>: The extension exclusively supports <code>.xlsx</code> spreadsheet files. Other spreadsheet formats are not supported for uploads.</p></div><hr><h2 id="excel-source-type-selection" tabindex="-1">Excel Source Type Selection <a class="header-anchor" href="#excel-source-type-selection" aria-label="Permalink to “Excel Source Type Selection”">​</a></h2><p>Within your Site workspace, open the <strong>Upload Excel</strong> tab. Use the <strong>Excel Source Type</strong> radio toggle to select your data source:</p><table tabindex="0"><thead><tr><th>Source Type</th><th>Description</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Upload Excel File</strong></td><td>Direct upload of a local <code>.xlsx</code> workbook into extension storage.</td><td>Fast execution, offline workflows, standalone automation tasks.</td></tr><tr><td><strong>Google Sheet (Beta)</strong></td><td>Live cloud connection via Google Sheets API (OAuth2 or Service Account).</td><td>Team collaboration, real-time data entry, multi-browser distributed processing.</td></tr></tbody></table><hr><h2 id="upload-excel-file" tabindex="-1">Method 1: Upload Excel File <a class="header-anchor" href="#upload-excel-file" aria-label="Permalink to “Method 1: Upload Excel File”">​</a></h2><p>Follow these steps to upload and manage local Excel files:</p><h3 id="step-1-select-upload-excel-file" tabindex="-1">Step 1: Select Upload Excel File <a class="header-anchor" href="#step-1-select-upload-excel-file" aria-label="Permalink to “Step 1: Select Upload Excel File”">​</a></h3><ol><li>Navigate to the <strong>Upload Excel</strong> tab in your site workspace.</li><li>Select the <strong>Upload Excel File</strong> option under <strong>Excel Source Type</strong>.</li></ol><h3 id="step-2-upload-your-xlsx-file" tabindex="-1">Step 2: Upload Your <code>.xlsx</code> File <a class="header-anchor" href="#step-2-upload-your-xlsx-file" aria-label="Permalink to “Step 2: Upload Your .xlsx File”">​</a></h3><ol><li>Under <strong>Select Excel File (.xlsx) for Upload</strong>, click inside the upload box or drag and drop your file.</li><li>Select your <code>.xlsx</code> workbook from your computer.</li><li>Click <strong>Save Excel Template</strong> to store the workbook in the extension.</li></ol><img src="/image/download-excel-template-01.png" alt="Download and Save Excel Template Interface" style="max-width:100%;border-radius:8px;margin:16px 0;"><h3 id="available-toolbar-actions" tabindex="-1">Available Toolbar Actions <a class="header-anchor" href="#available-toolbar-actions" aria-label="Permalink to “Available Toolbar Actions”">​</a></h3><table tabindex="0"><thead><tr><th>Action Button</th><th>Purpose</th><th>Details</th></tr></thead><tbody><tr><td><strong>Save Excel Template</strong></td><td>Commit and save dataset</td><td>Saves the uploaded <code>.xlsx</code> data into local extension storage for the active site.</td></tr><tr><td><strong>Download Excel Template</strong></td><td>Generate <code>.xlsx</code> template</td><td>Creates a ready-to-fill <code>.xlsx</code> spreadsheet pre-populated with column headers matching your configured form fields.</td></tr><tr><td><strong>Delete Excel</strong> (Trash Icon)</td><td>Clear uploaded data</td><td>Removes the current Excel dataset from extension storage.</td></tr></tbody></table><h3 id="excel-data-status-states" tabindex="-1">Excel Data Status States <a class="header-anchor" href="#excel-data-status-states" aria-label="Permalink to “Excel Data Status States”">​</a></h3><ul><li><strong>When No Excel File is Uploaded</strong>:<div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Not Found</span></span>
<span class="line"><span>Excel Data Not Available, Please Upload Excel File.</span></span></code></pre></div></li><li><strong>When Excel File is Successfully Uploaded</strong>: <ul><li>The records become immediately accessible for automation.</li><li>You can inspect loaded rows and column mappings under the <strong>Excel Data</strong> tab.</li><li>The extension tracks row indexes during automation runs.</li></ul></li></ul><hr><h2 id="google-sheet-beta" tabindex="-1">Method 2: Google Sheet (Beta) <a class="header-anchor" href="#google-sheet-beta" aria-label="Permalink to “Method 2: Google Sheet (Beta)”">​</a></h2><p>Connect directly to cloud spreadsheets in Google Drive for live data streaming and bidirectional sync.</p><h3 id="connection-types" tabindex="-1">Connection Types <a class="header-anchor" href="#connection-types" aria-label="Permalink to “Connection Types”">​</a></h3><p>Google Sheet integration supports two distinct authentication methods:</p><h4 id="oauth2-login" tabindex="-1">1. OAuth2 (Login Required) <a class="header-anchor" href="#oauth2-login" aria-label="Permalink to “1. OAuth2 (Login Required)”">​</a></h4><p>Connect using your Google account via standard OAuth2 authentication.</p><ul><li><strong>Requirements</strong>: Active Google account with access permissions to the target spreadsheet and an internet connection.</li><li><strong>Setup</strong>: <ol><li>Select the <strong>Google Sheet (Beta)</strong> radio button.</li><li>Choose <strong>OAuth2 (Login Required)</strong>.</li><li>Click <strong>Check Account Connection</strong>.</li><li>Follow the Google OAuth popup prompt to sign in and grant spreadsheet read/write permissions.</li></ol></li></ul><h4 id="service-account" tabindex="-1">2. Client Service Account (No Login Required) <a class="header-anchor" href="#service-account" aria-label="Permalink to “2. Client Service Account (No Login Required)”">​</a></h4><p>Connect securely via a Google Cloud Console service account without requiring browser user logins.</p><ul><li><strong>Requirements</strong>: <ul><li>A Google Cloud Platform (GCP) project with the Google Sheets API enabled.</li><li>A Service Account with an exported JSON key file containing <code>client_email</code> and <code>private_key</code>.</li><li>The Google Sheet must be shared with the Service Account email address (<code>Editor</code> permissions).</li></ul></li><li><strong>Setup</strong>: <ol><li>Select the <strong>Google Sheet (Beta)</strong> radio button.</li><li>Choose <strong>Client (Service Account, No Login Required)</strong>.</li><li>Click <strong>Click to Upload JSON File</strong> and select your downloaded service account <code>.json</code> key file.</li><li>Ensure your Google Sheet is shared with the service account email.</li></ol></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Service Account Sharing</strong>: Always open your Google Sheet, click <strong>Share</strong>, and paste the Service Account email (<code>...iam.gserviceaccount.com</code>) as an <strong>Editor</strong> to allow reading and updating rows.</p></div><hr><h2 id="google-sheet-configuration" tabindex="-1">Google Sheet Configuration <a class="header-anchor" href="#google-sheet-configuration" aria-label="Permalink to “Google Sheet Configuration”">​</a></h2><h3 id="required-connection-fields" tabindex="-1">Required Connection Fields <a class="header-anchor" href="#required-connection-fields" aria-label="Permalink to “Required Connection Fields”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Spreadsheet URL</strong></td><td>Full web URL of the Google Spreadsheet.</td><td><code>https://docs.google.com/spreadsheets/d/1A2B3C4D5E6F7G8H9.../edit</code></td></tr><tr><td><strong>Spreadsheet Sheet Name</strong></td><td>Exact name of the sheet/tab containing your data (case-sensitive).</td><td><code>Sheet1</code>, <code>Orders</code>, <code>FormData</code></td></tr><tr><td><strong>How many rows of the sheet to fetch?</strong></td><td>Maximum number of rows to retrieve per batch.</td><td><code>30</code>, <code>50</code>, <code>100</code></td></tr></tbody></table><h3 id="optional-advanced-features" tabindex="-1">Optional Advanced Features <a class="header-anchor" href="#optional-advanced-features" aria-label="Permalink to “Optional Advanced Features”">​</a></h3><h4 id="browser-id" tabindex="-1">Fetch Sheet Row Data Using Browser ID <a class="header-anchor" href="#browser-id" aria-label="Permalink to “Fetch Sheet Row Data Using Browser ID”">​</a></h4><p>Enables running multiple browser instances or profiles concurrently against the same sheet without row collision.</p><ul><li><strong>How it works</strong>: <ol><li>Toggle <strong>Fetch Sheet Row Data Using Browser Id</strong>.</li><li>Enter identifier names in the Browser ID field (e.g., <code>browser-1</code>, <code>browser-2</code>).</li><li>In your Google Sheet, create a column named <code>&lt;code v-pre&gt;{BROWSER-ID}&lt;/code&gt;</code>.</li><li>Assign the appropriate browser ID value to each row.</li><li>The extension instance will only fetch and fill rows designated for its configured Browser ID.</li></ol></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The column header in your Google Sheet must be spelled exactly <code>&lt;code v-pre&gt;{BROWSER-ID}&lt;/code&gt;</code> (including curly braces).</p></div><h4 id="ignore-columns" tabindex="-1">Ignore Column Values When Updating <a class="header-anchor" href="#ignore-columns" aria-label="Permalink to “Ignore Column Values When Updating”">​</a></h4><p>Protects specific columns from being overwritten when pushing site data updates back to the sheet.</p><ul><li><strong>How to use</strong>: <ol><li>Toggle <strong>Ignore column values when updating the sheet?</strong>.</li><li>Enter the column names you wish to preserve (e.g., <code>Status</code>, <code>Notes</code>, <code>DateAdded</code>), pressing Enter after each entry.</li><li>These columns will be retained untouched during sync operations.</li></ol></li></ul><hr><h2 id="google-sheet-actions" tabindex="-1">Google Sheet Management Actions <a class="header-anchor" href="#google-sheet-actions" aria-label="Permalink to “Google Sheet Management Actions”">​</a></h2><h3 id="check-account-connection" tabindex="-1">Check Account Connection <a class="header-anchor" href="#check-account-connection" aria-label="Permalink to “Check Account Connection”">​</a></h3><p>Tests and confirms your Google account authentication or Service Account JSON validity.</p><ul><li><strong>OAuth2</strong>: Triggers authentication verification with Google servers.</li><li><strong>Service Account</strong>: Validates the uploaded JSON key format and cryptographic credentials.</li></ul><h3 id="check-sheet-connection" tabindex="-1">Check Sheet Connection <a class="header-anchor" href="#check-sheet-connection" aria-label="Permalink to “Check Sheet Connection”">​</a></h3><p>Verifies network access, spreadsheet URL validity, and sheet tab existence. Confirms that headers and rows can be fetched properly.</p><h3 id="update-sheet-with-site-data" tabindex="-1">Update Sheet With Site Data <a class="header-anchor" href="#update-sheet-with-site-data" aria-label="Permalink to “Update Sheet With Site Data”">​</a></h3><p>Synchronizes your configured form fields with the Google Sheet structure.</p><ul><li>Inspects all form fields registered in the active site.</li><li>Generates or updates column headers in the target sheet to match field names.</li><li>Configures schema alignment for seamless two-way data filling and status reporting.</li></ul><h3 id="clear-sheet-cache" tabindex="-1">Clear Sheet Cache <a class="header-anchor" href="#clear-sheet-cache" aria-label="Permalink to “Clear Sheet Cache”">​</a></h3><p>Flushes locally cached Google Sheet data, forcing the extension to pull fresh records on the next automation cycle.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Always click <strong>Clear Sheet Cache</strong> whenever you edit cell values, insert rows, or add new columns directly inside Google Sheets.</p></div><hr><h2 id="download-excel-template" tabindex="-1">Excel Template Download <a class="header-anchor" href="#download-excel-template" aria-label="Permalink to “Excel Template Download”">​</a></h2><p>Generating an Excel template ensures your local <code>.xlsx</code> file matches your form field names with 100% precision:</p><ol><li>Configure all form fields in your site.</li><li>Under the <strong>Upload Excel</strong> tab, click <strong>Download Excel Template</strong>.</li><li>The extension compiles an <code>.xlsx</code> workbook containing: <ul><li>Header row matching every active field name.</li><li>Proper column sequencing.</li><li>Clean column layout ready for batch data entry.</li></ul></li><li>Open the downloaded file in Microsoft Excel or compatible software, populate your rows, and upload it back into the extension.</li></ol><ul><li><strong>Output File Naming Format</strong>: <code>[SiteName]_Template_[Date].xlsx</code></li></ul><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before uploading data or downloading templates, ensure:</p><ol><li><strong>Site Created</strong>: A parent site container exists in the extension.</li><li><strong>Forms Registered</strong>: At least one form page is added under the site.</li><li><strong>Fields Configured</strong>: Form fields have assigned element selectors and field types.</li><li><strong>Valid Names</strong>: Field names are clear and descriptive to generate readable <code>.xlsx</code> column headers.</li></ol><hr><h2 id="workflows" tabindex="-1">Automation Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to “Automation Workflows”">​</a></h2><h3 id="local-excel-xlsx-workflow" tabindex="-1">Local Excel (<code>.xlsx</code>) Workflow <a class="header-anchor" href="#local-excel-xlsx-workflow" aria-label="Permalink to “Local Excel (.xlsx) Workflow”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Configure Fields] ──&gt; [Download .xlsx Template] ──&gt; [Populate Rows] ──&gt; [Upload .xlsx] ──&gt; [Run Automation]</span></span></code></pre></div><ol><li><strong>Download Template</strong>: Click <strong>Download Excel Template</strong> to obtain the current field schema.</li><li><strong>Populate Rows</strong>: Fill records into the <code>.xlsx</code> sheet.</li><li><strong>Upload Workbook</strong>: Upload via <strong>Select Excel File (.xlsx) for Upload</strong> and click <strong>Save Excel Template</strong>.</li><li><strong>Execute</strong>: Trigger form filling with <kbd>Alt</kbd> + <kbd>Q</kbd> or on page load.</li></ol><h3 id="google-sheets-workflow" tabindex="-1">Google Sheets Workflow <a class="header-anchor" href="#google-sheets-workflow" aria-label="Permalink to “Google Sheets Workflow”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Connect OAuth2 / Service Account] ──&gt; [Set URL &amp; Sheet Name] ──&gt; [Update Sheet With Site Data] ──&gt; [Fill Rows] ──&gt; [Run Automation]</span></span></code></pre></div><ol><li><strong>Authenticate</strong>: Connect using OAuth2 or upload Service Account JSON.</li><li><strong>Configure</strong>: Provide the Spreadsheet URL and Sheet Tab Name.</li><li><strong>Structure Sync</strong>: Click <strong>Update Sheet With Site Data</strong> to create headers automatically.</li><li><strong>Input Data</strong>: Enter data into the Google Sheet.</li><li><strong>Execute</strong>: Run automation. If edits are made in the sheet, click <strong>Clear Sheet Cache</strong>.</li></ol><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="local-excel-issues" tabindex="-1">Local Excel Issues <a class="header-anchor" href="#local-excel-issues" aria-label="Permalink to “Local Excel Issues”">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Template not downloading</strong></td><td>Missing form fields or browser permission issue</td><td>Ensure at least one form with fields is configured. Check browser download settings.</td></tr><tr><td><strong>Excel file will not upload</strong></td><td>Unsupported file format or corrupted file</td><td>Ensure the file is strictly <code>.xlsx</code>. Re-save the file in Excel if needed.</td></tr><tr><td><strong>Data not filling into form</strong></td><td>Header mismatch with field names</td><td>Download a fresh template to verify column headers match field names exactly.</td></tr></tbody></table><h3 id="google-sheet-issues" tabindex="-1">Google Sheet Issues <a class="header-anchor" href="#google-sheet-issues" aria-label="Permalink to “Google Sheet Issues”">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Cannot connect Google account</strong></td><td>Expired OAuth session or network block</td><td>Re-click <strong>Check Account Connection</strong> and complete the Google login prompt.</td></tr><tr><td><strong>Sheet connection failed</strong></td><td>Incorrect URL, sheet name mismatch, or missing permissions</td><td>Verify the URL and tab name (case-sensitive). For Service Accounts, verify the sheet is shared with the service account email as Editor.</td></tr><tr><td><strong>Data changes not appearing</strong></td><td>Local cache active</td><td>Click <strong>Clear Sheet Cache</strong> to fetch the latest cloud rows.</td></tr><tr><td><strong>Browser ID filtering not working</strong></td><td>Header misspelling or missing column</td><td>Confirm the column header is named <code>&lt;code v-pre&gt;{BROWSER-ID}&lt;/code&gt;</code> and row values match the configured ID.</td></tr></tbody></table><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><h3 id="do-s" tabindex="-1">Do&#39;s <a class="header-anchor" href="#do-s" aria-label="Permalink to “Do&#39;s”">​</a></h3><ul><li><strong>Download Fresh Templates</strong>: Download a new <code>.xlsx</code> template whenever you add, rename, or remove form fields.</li><li><strong>Match Header Names</strong>: Ensure column names match field names accurately.</li><li><strong>Clear Cache on Sheet Edits</strong>: Always click <strong>Clear Sheet Cache</strong> after updating Google Sheet data.</li><li><strong>Test with Sample Rows</strong>: Test automation on 2-3 rows before processing large datasets.</li><li><strong>Use Browser IDs for Scale</strong>: Use <code>&lt;code v-pre&gt;{BROWSER-ID}&lt;/code&gt;</code> when distributing work across multiple profiles or devices.</li></ul><h3 id="don-ts" tabindex="-1">Don&#39;ts <a class="header-anchor" href="#don-ts" aria-label="Permalink to “Don&#39;ts”">​</a></h3><ul><li><strong>Do Not Use Non-XLSX Formats</strong>: Upload local data exclusively in <code>.xlsx</code> format.</li><li><strong>Do Not Rename Headers Manually</strong>: Avoid altering generated template column headers.</li><li><strong>Do Not Leave Formulas Uncalculated</strong>: If your spreadsheet uses complex formulas, ensure values are resolved before running automation.</li><li><strong>Do Not Expose Service Account Keys</strong>: Keep your Google Cloud JSON credentials safe and confidential.</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/site/site.html">Site Management</a></li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-scraper-data.html">Scraper Data</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a></li><li><img src="/svg/card.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Fields</a></li><li><img src="/svg/database.svg" class="doc-icon"> <a href="/documentation/form-fields/field-types.html">Field Types</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Logs &amp; Execution Tracking</a></li></ul>`,94)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};